    14	/** Append-only revision log, stored the way the database table holds it (encoded text). */
    15	export class RevisionStore {
    16	  private readonly rows: Row[] = [];
    17	  private readonly latestIndex = new Map<string, number>();
    18	
    19	  append(deviceId: string, profile: DeviceProfile, source: RevisionSource, createdAt: number, changed: string[]): Revision {
    20	    const prev = this.latest(deviceId);
    21	    const row: Row = {
    22	      deviceId,
    23	      rev: prev ? prev.rev + 1 : 1,
    24	      createdAt,
    25	      source,
    26	      body: encodeProfile(profile),
    27	      changed: changed.join(","),
    28	    };
    29	    this.rows.push(row);
    30	    this.latestIndex.set(deviceId, this.rows.length - 1);
    31	    return this.toRevision(row);
    32	  }
